// Selected official ActivityDomainBossRankPanel; generated by prepare_activity_battle_rank_ui.py.
using Zjcs.Official.WorldUI;
using Zjcs.Official.ProfessionUI;
using Zjcs.Official.TeamUI;
namespace Zjcs.Official.ActivityRankUI
{
using UnityEngine;

public class ActivityDomainBossRankPanel : UIBase
{
	[SerializeField]
	private TeamTopContent mTeamTopContent;

	[SerializeField]
	private SwitchTopRangeBtn mSwitchTopRangeBtn;

	[SerializeField]
	private TeamTopContentDataBase mTopContentData;

	[SerializeField]
	private RuleBtn mRuleBtn;

	private int mActivityId;

	private string mRuleKey;

	public void Configure(ActivityRankBindings bindings)
	{ mTeamTopContent.Configure(bindings); mSwitchTopRangeBtn.Configure(bindings.CanSwitchRange); if (mRuleBtn != null) mRuleBtn.Configure(bindings.OpenRule); }

	public void Init(int activityId, string ruleKey)
	{
		InitWrapper(() =>
		{
			mActivityId = activityId;
			mRuleKey = ruleKey;
		});
	}

	protected override void OnEnableAndInited()
	{
		base.OnEnableAndInited();
		mSwitchTopRangeBtn.SetListener(OnTopRangeChanged);
		if ((Object)(object)mRuleBtn != (Object)null)
		{
			mRuleBtn.SetRuleKey(mRuleKey);
		}
		Refresh();
	}

	protected override void OnDisableAndInited()
	{
		mSwitchTopRangeBtn.SetListener(null);
		base.OnDisableAndInited();
	}

	private void OnTopRangeChanged()
	{
		TopRangeType rangeType = mSwitchTopRangeBtn.RangeType;
		if (mTeamTopContent.CurrentTopKey != null && mTeamTopContent.CurrentTopKey.RangeType != rangeType)
		{
			mTeamTopContent.CurrentTopKey.RangeType = rangeType;
			mTeamTopContent.RefreshContent();
		}
	}

	private void InitRankData()
	{
		mTeamTopContent.Init(new ActivityDomainBossRankKey(mActivityId, mSwitchTopRangeBtn.RangeType), mTopContentData);
	}

	private void Refresh()
	{
		mSwitchTopRangeBtn.SetActive();
		InitRankData();
	}
}
}
